import math

def is_perfect_cube(n):
    if n == 0:
        return 0
    # Handle negative numbers by taking the cube root of the absolute value and negating
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Estimate the cube root
    root = round(n**(1/3))

    # Check if it's a perfect cube
    if root**3 == n:
        return sign * root
    return None

def E(x):
    return (8*x - 41) * (x + 3)**2

results = {}
for x in range(-5, 16):
    e_x = E(x)
    cube_root = is_perfect_cube(e_x)
    if cube_root is not None:
        results[x] = cube_root

print(results)

